{
  "application": "data-visualization",
  "case_id": "case-health-global-disease-burden-daly-shift-1990-2024",
  "language": "en",
  "style": {
    "theme": "editorial",
    "audience": "researchers and policy makers",
    "tone": "authoritative, publication-ready, data-dense"
  },
  "goal": [
    {
      "id": "structural-transition",
      "insight": "Visually contrast the shift from communicable-disease-dominated DALY burden in 1990 to chronic/NCD-dominated burden in 2024, making the structural transition immediately apparent"
    },
    {
      "id": "income-group-disparity",
      "insight": "Highlight the stark differences in disease burden composition across World Bank income groups, showing that low-income countries retain a high communicable disease share while high-income countries are overwhelmingly NCD-dominated"
    },
    {
      "id": "top-cause-rank-change",
      "insight": "Emphasize the rank changes of the top 10 DALY causes between 1990 and 2024, making large rank shifts (e.g., lower respiratory infections dropping, ischemic heart disease rising) visually prominent"
    },
    {
      "id": "communicable-vs-ncd-share",
      "insight": "Show the aggregate communicable vs NCD vs injury share of total DALYs for each income group in both years, so the viewer can compare proportions at a glance"
    },
    {
      "id": "encoding-mapping",
      "insight": "Use color coding to consistently distinguish communicable diseases, non-communicable diseases, and injuries across all panels and datasets"
    }
  ]
}

